        if (std.mem.eql(u8, discriminator.string, "function")) {
            return .{ .function = try std.json.parseFromValueLeaky(LiveFunctionToolChoiceParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "mcp")) {
            return .{ .mcp = try std.json.parseFromValueLeaky(LiveMCPToolChoiceParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "file_search")) {
            return .{ .file_search = try std.json.parseFromValueLeaky(LiveSpecificFileSearchParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "web_search")) {
            return .{ .web_search = try std.json.parseFromValueLeaky(LiveSpecificWebSearchParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "web_search_preview")) {
            return .{ .web_search_preview = try std.json.parseFromValueLeaky(LiveSpecificWebSearchPreviewParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "image_generation")) {
            return .{ .image_generation = try std.json.parseFromValueLeaky(LiveSpecificImageGenParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "computer")) {
            return .{ .computer = try std.json.parseFromValueLeaky(LiveSpecificComputerParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "code_interpreter")) {
            return .{ .code_interpreter = try std.json.parseFromValueLeaky(LiveSpecificCodeInterpreterParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "programmatic_tool_calling")) {
            return .{ .programmatic_tool_calling = try std.json.parseFromValueLeaky(LiveSpecificProgrammaticToolCallingParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "shell")) {
            return .{ .shell = try std.json.parseFromValueLeaky(LiveSpecificFunctionShellParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "custom")) {
            return .{ .custom = try std.json.parseFromValueLeaky(LiveSpecificCustomToolParam, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "apply_patch")) {
            return .{ .apply_patch = try std.json.parseFromValueLeaky(LiveSpecificApplyPatchParam, allocator, source, options) };
        }

        return .{ .raw = source };
    }

    pub fn jsonStringify(self: @This(), jw: *std.json.Stringify) !void {
        switch (self) {
            .function => |value| try jw.write(value),
            .mcp => |value| try jw.write(value),
            .file_search => |value| try jw.write(value),
            .web_search => |value| try jw.write(value),
            .web_search_preview => |value| try jw.write(value),
            .image_generation => |value| try jw.write(value),
            .computer => |value| try jw.write(value),
            .code_interpreter => |value| try jw.write(value),
            .programmatic_tool_calling => |value| try jw.write(value),
            .shell => |value| try jw.write(value),
            .custom => |value| try jw.write(value),
            .apply_patch => |value| try jw.write(value),
            .raw => |value| try jw.write(value),
        }
    }
};

