        }

        return .{ .raw = source };
    }

    pub fn jsonStringify(self: @This(), jw: *std.json.Stringify) !void {
        switch (self) {
            .function => |value| try jw.write(value),
            .custom => |value| try jw.write(value),
            .raw => |value| try jw.write(value),
        }
    }
};

