pub const BetaFunctionAndCustomToolCallOutput = union(enum) {
    input_text: BetaInputTextContent,
    input_image: BetaInputImageContent,
    input_file: BetaInputFileContent,
    raw: std.json.Value,

    pub fn jsonParse(allocator: std.mem.Allocator, source: anytype, options: std.json.ParseOptions) !@This() {
        const value = try std.json.innerParse(std.json.Value, allocator, source, options);
        return jsonParseFromValue(allocator, value, options);
    }

    pub fn jsonParseFromValue(allocator: std.mem.Allocator, source: std.json.Value, options: std.json.ParseOptions) !@This() {
        if (source != .object) return error.UnexpectedToken;
        const discriminator = source.object.get("type") orelse return .{ .raw = source };
        if (discriminator != .string) return .{ .raw = source };
        if (std.mem.eql(u8, discriminator.string, "input_text")) {
            return .{ .input_text = try std.json.parseFromValueLeaky(BetaInputTextContent, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "input_image")) {
            return .{ .input_image = try std.json.parseFromValueLeaky(BetaInputImageContent, allocator, source, options) };
        }
        if (std.mem.eql(u8, discriminator.string, "input_file")) {
            return .{ .input_file = try std.json.parseFromValueLeaky(BetaInputFileContent, allocator, source, options) };
        }

        return .{ .raw = source };
    }

    pub fn jsonStringify(self: @This(), jw: *std.json.Stringify) !void {
        switch (self) {
            .input_text => |value| try jw.write(value),
            .input_image => |value| try jw.write(value),
            .input_file => |value| try jw.write(value),
            .raw => |value| try jw.write(value),
        }
    }
};

